/Table[@Name='Ingredient' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Branch_Ingredient]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Branch_Ingredient' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Branch_Ingredient]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Branch_Ingredient](\r\n\t[branch_id] [int] NOT NULL,\r\n\t[ingredient_id] [int] NOT NULL,\r\n\t[current_stock] [decimal](12, 2) NOT NULL,\r\n\t[cost_per_unit] [decimal](12, 2) NOT NULL,\r\n\t[min_stock_threshold] [decimal](12, 2) NOT NULL,\r\n CONSTRAINT [PK_Branch_Ingredient] PRIMARY KEY CLUSTERED \r\n(\r\n\t[branch_id] ASC,\r\n\t[ingredient_id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Branch_Ingredient' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Branch]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Branch' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Branch]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Branch](\r\n\t[id] [int] IDENTITY(1,1) NOT NULL,\r\n\t[name] [nvarchar](100) NOT NULL,\r\n\t[address] [nvarchar](255) NOT NULL,\r\n\t[phone] [varchar](20) NULL,\r\n\t[email] [varchar](100) NULL,\r\n\t[is_deleted] [bit] NOT NULL,\r\n\t[deleted_at] [datetime2](7) NULL,\r\n\t[created_at] [datetime2](7) NOT NULL,\r\n\t[updated_at] [datetime2](7) NOT NULL,\r\nPRIMARY KEY CLUSTERED \r\n(\r\n\t[id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Branch' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[vw_Stock_Status]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Stock_Status' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  View [dbo].[vw_Stock_Status]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- ================================================================\r\n-- PHẦN 11: VIEWS HỖ TRỢ BACKEND / BÁO CÁO\r\n-- ================================================================\r\n\r\n-- View: Tồn kho với trạng thái cảnh báo\r\nCREATE   VIEW [dbo].[vw_Stock_Status] AS\r\nSELECT\r\n    b.name          AS branch_name,\r\n    i.name          AS ingredient_name,\r\n    i.unit,\r\n    bi.current_stock,\r\n    bi.min_stock_threshold,\r\n    bi.cost_per_unit,\r\n    CASE\r\n        WHEN bi.current_stock <= 0                              THEN N'Hết hàng'\r\n        WHEN bi.current_stock < bi.min_stock_threshold          THEN N'Sắp hết'\r\n        WHEN bi.current_stock < bi.min_stock_threshold * 1.5   THEN N'Còn ít'\r\n        ELSE                                                         N'Đủ hàng'\r\n    END AS stock_status\r\nFROM Branch_Ingredient bi\r\nJOIN Branch      b ON b.id = bi.branch_id\r\nJOIN Ingredient  i ON i.id = bi.ingredient_id\r\nWHERE b.is_deleted = 0 AND i.is_deleted = 0;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Stock_Status' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[Category]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Category' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Category]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Category](\r\n\t[id] [int] IDENTITY(1,1) NOT NULL,\r\n\t[name] [nvarchar](100) NOT NULL,\r\nPRIMARY KEY CLUSTERED \r\n(\r\n\t[id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Category' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Menu_Item]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Menu_Item' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Menu_Item]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Menu_Item](\r\n\t[id] [int] IDENTITY(1,1) NOT NULL,\r\n\t[category_id] [int] NOT NULL,\r\n\t[name] [nvarchar](100) NOT NULL,\r\n\t[price] [decimal](12, 2) NOT NULL,\r\n\t[image_url] [nvarchar](500) NULL,\r\n\t[is_available] [bit] NOT NULL,\r\n\t[description] [nvarchar](500) NULL,\r\n\t[is_deleted] [bit] NOT NULL,\r\n\t[deleted_at] [datetime2](7) NULL,\r\n\t[created_at] [datetime2](7) NOT NULL,\r\n\t[updated_at] [datetime2](7) NOT NULL,\r\nPRIMARY KEY CLUSTERED \r\n(\r\n\t[id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Menu_Item' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Recipe]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Recipe' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Recipe]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Recipe](\r\n\t[menu_item_id] [int] NOT NULL,\r\n\t[ingredient_id] [int] NOT NULL,\r\n\t[quantity_required] [decimal](12, 4) NOT NULL,\r\n CONSTRAINT [PK_Recipe] PRIMARY KEY CLUSTERED \r\n(\r\n\t[menu_item_id] ASC,\r\n\t[ingredient_id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Recipe' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[vw_MenuItem_Profit]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_MenuItem_Profit' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  View [dbo].[vw_MenuItem_Profit]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- View: Chi phí & lợi nhuận món theo chi nhánh\r\nCREATE   VIEW [dbo].[vw_MenuItem_Profit] AS\r\nSELECT\r\n    b.id            AS branch_id,\r\n    b.name          AS branch_name,\r\n    m.id            AS menu_item_id,\r\n    m.name          AS item_name,\r\n    m.price,\r\n    m.is_available,\r\n    ISNULL(SUM(r.quantity_required * bi.cost_per_unit), 0)              AS cost_price,\r\n    m.price - ISNULL(SUM(r.quantity_required * bi.cost_per_unit), 0)   AS profit,\r\n    CASE\r\n        WHEN m.price = 0 THEN 0\r\n        ELSE ROUND(\r\n            (m.price - ISNULL(SUM(r.quantity_required * bi.cost_per_unit), 0))\r\n            / m.price * 100, 2)\r\n    END AS profit_margin_pct\r\nFROM Menu_Item m\r\nJOIN Category           c  ON c.id  = m.category_id\r\nLEFT JOIN Recipe        r  ON r.menu_item_id  = m.id\r\nLEFT JOIN Branch_Ingredient bi ON bi.ingredient_id = r.ingredient_id\r\nLEFT JOIN Branch        b  ON b.id  = bi.branch_id\r\nWHERE m.is_deleted = 0\r\nGROUP BY b.id, b.name, m.id, m.name, m.price, m.is_available;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_MenuItem_Profit' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[Order]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Order' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Order]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Order](\r\n\t[id] [bigint] IDENTITY(1,1) NOT NULL,\r\n\t[branch_id] [int] NOT NULL,\r\n\t[shift_id] [bigint] NULL,\r\n\t[customer_id] [int] NULL,\r\n\t[order_status_id] [int] NOT NULL,\r\n\t[table_id] [int] NULL,\r\n\t[order_type] [varchar](20) NOT NULL,\r\n\t[sub_total] [decimal](15, 2) NOT NULL,\r\n\t[discount_amount] [decimal](15, 2) NOT NULL,\r\n\t[final_amount] [decimal](15, 2) NOT NULL,\r\n\t[cost_amount] [decimal](15, 2) NOT NULL,\r\n\t[note] [nvarchar](500) NULL,\r\n\t[is_deleted] [bit] NOT NULL,\r\n\t[deleted_at] [datetime2](7) NULL,\r\n\t[created_at] [datetime2](7) NOT NULL,\r\n\t[updated_at] [datetime2](7) NOT NULL,\r\nPRIMARY KEY CLUSTERED \r\n(\r\n\t[id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Order' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[vw_Revenue_By_Hour]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Revenue_By_Hour' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  View [dbo].[vw_Revenue_By_Hour]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- View: Doanh thu theo giờ (hôm nay)\r\nCREATE   VIEW [dbo].[vw_Revenue_By_Hour] AS\r\nSELECT\r\n    branch_id,\r\n    DATEPART(HOUR, created_at)      AS hour_of_day,\r\n    COUNT(*)                        AS total_orders,\r\n    SUM(final_amount)               AS total_revenue,\r\n    SUM(cost_amount)                AS total_cost,\r\n    SUM(final_amount - cost_amount) AS total_profit\r\nFROM [Order]\r\nWHERE is_deleted = 0\r\n  AND order_status_id = 4          -- COMPLETED\r\n  AND CAST(created_at AS DATE) = CAST(SYSDATETIME() AS DATE)\r\nGROUP BY branch_id, DATEPART(HOUR, created_at);\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Revenue_By_Hour' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[Order_Status]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Order_Status' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Order_Status]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Order_Status](\r\n\t[id] [int] IDENTITY(1,1) NOT NULL,\r\n\t[name] [varchar](50) NOT NULL,\r\nPRIMARY KEY CLUSTERED \r\n(\r\n\t[id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Order_Status' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[vw_Dashboard_Today]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Dashboard_Today' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  View [dbo].[vw_Dashboard_Today]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- View: Dashboard tổng quan hôm nay\r\nCREATE   VIEW [dbo].[vw_Dashboard_Today] AS\r\nSELECT\r\n    o.branch_id,\r\n    COUNT(*)                                                AS total_orders,\r\n    SUM(o.final_amount)                                     AS total_revenue,\r\n    SUM(o.cost_amount)                                      AS total_cost,\r\n    SUM(o.final_amount - o.cost_amount)                     AS total_profit,\r\n    SUM(CASE WHEN os.name = 'CANCELLED' THEN 1 ELSE 0 END) AS cancelled_orders,\r\n    SUM(CASE WHEN os.name = 'CANCELLED' THEN o.final_amount ELSE 0 END) AS cancelled_revenue_loss,\r\n    AVG(o.final_amount)                                     AS avg_order_value\r\nFROM [Order] o\r\nJOIN Order_Status os ON os.id = o.order_status_id\r\nWHERE o.is_deleted = 0\r\n  AND CAST(o.created_at AS DATE) = CAST(SYSDATETIME() AS DATE)\r\nGROUP BY o.branch_id;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Dashboard_Today' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[Work_Shift]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Work_Shift' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Work_Shift]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Work_Shift](\r\n\t[id] [bigint] IDENTITY(1,1) NOT NULL,\r\n\t[branch_id] [int] NOT NULL,\r\n\t[employee_id] [int] NOT NULL,\r\n\t[account_id] [int] NULL,\r\n\t[start_time] [datetime2](7) NOT NULL,\r\n\t[end_time] [datetime2](7) NULL,\r\n\t[starting_cash] [decimal](15, 2) NOT NULL,\r\n\t[actual_ending_cash] [decimal](15, 2) NULL,\r\n\t[expected_cash] [decimal](15, 2) NULL,\r\n\t[difference] [decimal](15, 2) NULL,\r\n\t[status] [varchar](20) NOT NULL,\r\n\t[note] [nvarchar](500) NULL,\r\nPRIMARY KEY CLUSTERED \r\n(\r\n\t[id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Work_Shift' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[Employee]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Employee' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Employee]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Employee](\r\n\t[id] [int] IDENTITY(1,1) NOT NULL,\r\n\t[branch_id] [int] NOT NULL,\r\n\t[full_name] [nvarchar](100) NOT NULL,\r\n\t[phone] [varchar](15) NOT NULL,\r\n\t[email] [varchar](100) NULL,\r\n\t[position] [nvarchar](50) NULL,\r\n\t[salary] [decimal](15, 2) NOT NULL,\r\n\t[hired_date] [date] NULL,\r\n\t[is_deleted] [bit] NOT NULL,\r\n\t[deleted_at] [datetime2](7) NULL,\r\n\t[created_at] [datetime2](7) NOT NULL,\r\n\t[updated_at] [datetime2](7) NOT NULL,\r\nPRIMARY KEY CLUSTERED \r\n(\r\n\t[id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Employee' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[vw_Staff_Performance_Today]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Staff_Performance_Today' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  View [dbo].[vw_Staff_Performance_Today]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- View: Hiệu suất nhân viên hôm nay\r\nCREATE   VIEW [dbo].[vw_Staff_Performance_Today] AS\r\nSELECT\r\n    ws.branch_id,\r\n    e.id        AS employee_id,\r\n    e.full_name,\r\n    e.position,\r\n    ws.start_time,\r\n    ws.end_time,\r\n    ws.status   AS shift_status,\r\n    COUNT(o.id)             AS total_orders,\r\n    SUM(o.final_amount)     AS total_revenue\r\nFROM Work_Shift ws\r\nJOIN Employee   e  ON e.id  = ws.employee_id\r\nLEFT JOIN [Order] o ON o.shift_id = ws.id AND o.is_deleted = 0\r\nWHERE CAST(ws.start_time AS DATE) = CAST(SYSDATETIME() AS DATE)\r\nGROUP BY ws.branch_id, e.id, e.full_name, e.position,\r\n         ws.start_time, ws.end_time, ws.status;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Staff_Performance_Today' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[Order_Item]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Order_Item' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Order_Item]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Order_Item](\r\n\t[id] [bigint] IDENTITY(1,1) NOT NULL,\r\n\t[order_id] [bigint] NOT NULL,\r\n\t[menu_item_id] [int] NOT NULL,\r\n\t[quantity] [int] NOT NULL,\r\n\t[unit_price] [decimal](12, 2) NOT NULL,\r\n\t[total_price]  AS ([quantity]*[unit_price]) PERSISTED,\r\n\t[note] [nvarchar](255) NULL,\r\nPRIMARY KEY CLUSTERED \r\n(\r\n\t[id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY = OFF, ALLOW_ROW_LOCKS = ON, ALLOW_PAGE_LOCKS = ON, OPTIMIZE_FOR_SEQUENTIAL_KEY = OFF) ON [PRIMARY]\r\n) ON [PRIMARY]\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Order_Item' and @Schema='dbo']","object_type":"Table"}},{"cell_type":"markdown","source":["# [dbo].[vw_Top_Items_30Days]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Top_Items_30Days' and @Schema='dbo']","object_type":"View"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  View [dbo].[vw_Top_Items_30Days]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- View: Top món bán chạy (30 ngày gần nhất)\r\nCREATE   VIEW [dbo].[vw_Top_Items_30Days] AS\r\nSELECT\r\n    o.branch_id,\r\n    m.id            AS menu_item_id,\r\n    m.name          AS item_name,\r\n    c.name          AS category_name,\r\n    SUM(oi.quantity)            AS total_quantity,\r\n    SUM(oi.total_price)         AS total_revenue,\r\n    RANK() OVER (\r\n        PARTITION BY o.branch_id\r\n        ORDER BY SUM(oi.quantity) DESC\r\n    ) AS rank_by_qty\r\nFROM Order_Item oi\r\nJOIN [Order]    o  ON o.id = oi.order_id\r\nJOIN Menu_Item  m  ON m.id = oi.menu_item_id\r\nJOIN Category   c  ON c.id = m.category_id\r\nWHERE o.is_deleted = 0\r\n  AND o.order_status_id = 4   -- COMPLETED\r\n  AND o.created_at >= DATEADD(DAY, -30, SYSDATETIME())\r\nGROUP BY o.branch_id, m.id, m.name, c.name;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/View[@Name='vw_Top_Items_30Days' and @Schema='dbo']","object_type":"View"}},{"cell_type":"markdown","source":["# [dbo].[Account]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Account' and @Schema='dbo']","object_type":"Table"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  Table [dbo].[Account]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","CREATE TABLE [dbo].[Account](\r\n\t[id] [int] IDENTITY(1,1) NOT NULL,\r\n\t[employee_id] [int] NOT NULL,\r\n\t[role_id] [int] NOT NULL,\r\n\t[username] [varchar](50) NOT NULL,\r\n\t[password_hash] [varchar](255) NOT NULL,\r\n\t[is_deleted] [bit] NOT NULL,\r\n\t[deleted_at] [datetime2](7) NULL,\r\n\t[created_at] [datetime2](7) NOT NULL,\r\n\t[updated_at] [datetime2](7) NOT NULL,\r\nPRIMARY KEY CLUSTERED \r\n(\r\n\t[id] ASC\r\n)WITH (PAD_INDEX = OFF, STATISTICS_NORECOMPUTE = OFF, IGNORE_DUP_KEY =