a":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Recipe' and @Schema='dbo']/Check[@Name='CK_Recipe_Qty']","object_type":"Check"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER TABLE [dbo].[Recipe]  WITH CHECK ADD  CONSTRAINT [CK_Recipe_Qty] CHECK  (([quantity_required]>(0)))\r\n","GO\r\n","ALTER TABLE [dbo].[Recipe] CHECK CONSTRAINT [CK_Recipe_Qty]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Recipe' and @Schema='dbo']/Check[@Name='CK_Recipe_Qty']","object_type":"Check"}},{"cell_type":"markdown","source":["# [CK_Refund_Amount]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Refund' and @Schema='dbo']/Check[@Name='CK_Refund_Amount']","object_type":"Check"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER TABLE [dbo].[Refund]  WITH CHECK ADD  CONSTRAINT [CK_Refund_Amount] CHECK  (([amount]>(0)))\r\n","GO\r\n","ALTER TABLE [dbo].[Refund] CHECK CONSTRAINT [CK_Refund_Amount]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Refund' and @Schema='dbo']/Check[@Name='CK_Refund_Amount']","object_type":"Check"}},{"cell_type":"markdown","source":["# [CK_Table_Cap]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Table_Cafe' and @Schema='dbo']/Check[@Name='CK_Table_Cap']","object_type":"Check"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER TABLE [dbo].[Table_Cafe]  WITH CHECK ADD  CONSTRAINT [CK_Table_Cap] CHECK  (([capacity]>(0)))\r\n","GO\r\n","ALTER TABLE [dbo].[Table_Cafe] CHECK CONSTRAINT [CK_Table_Cap]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Table_Cafe' and @Schema='dbo']/Check[@Name='CK_Table_Cap']","object_type":"Check"}},{"cell_type":"markdown","source":["# [CK_Table_Status]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Table_Cafe' and @Schema='dbo']/Check[@Name='CK_Table_Status']","object_type":"Check"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER TABLE [dbo].[Table_Cafe]  WITH CHECK ADD  CONSTRAINT [CK_Table_Status] CHECK  (([status]='CLEANING' OR [status]='OCCUPIED' OR [status]='EMPTY'))\r\n","GO\r\n","ALTER TABLE [dbo].[Table_Cafe] CHECK CONSTRAINT [CK_Table_Status]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Table_Cafe' and @Schema='dbo']/Check[@Name='CK_Table_Status']","object_type":"Check"}},{"cell_type":"markdown","source":["# [CK_Shift_Cash]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Work_Shift' and @Schema='dbo']/Check[@Name='CK_Shift_Cash']","object_type":"Check"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER TABLE [dbo].[Work_Shift]  WITH CHECK ADD  CONSTRAINT [CK_Shift_Cash] CHECK  (([starting_cash]>=(0)))\r\n","GO\r\n","ALTER TABLE [dbo].[Work_Shift] CHECK CONSTRAINT [CK_Shift_Cash]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Work_Shift' and @Schema='dbo']/Check[@Name='CK_Shift_Cash']","object_type":"Check"}},{"cell_type":"markdown","source":["# [CK_Shift_Status]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Work_Shift' and @Schema='dbo']/Check[@Name='CK_Shift_Status']","object_type":"Check"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER TABLE [dbo].[Work_Shift]  WITH CHECK ADD  CONSTRAINT [CK_Shift_Status] CHECK  (([status]='CLOSED' OR [status]='OPEN'))\r\n","GO\r\n","ALTER TABLE [dbo].[Work_Shift] CHECK CONSTRAINT [CK_Shift_Status]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/Table[@Name='Work_Shift' and @Schema='dbo']/Check[@Name='CK_Shift_Status']","object_type":"Check"}},{"cell_type":"markdown","source":["# [dbo].[sp_AddCustomerPoints]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/StoredProcedure[@Name='sp_AddCustomerPoints' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_AddCustomerPoints]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- SP: Cộng điểm khách hàng sau khi thanh toán\r\nCREATE   PROCEDURE [dbo].[sp_AddCustomerPoints]\r\n    @customer_id    INT,\r\n    @order_amount   DECIMAL(15,2)\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    -- Quy tắc: 1 điểm cho mỗi 1.000đ\r\n    DECLARE @points_to_add INT = FLOOR(@order_amount / 1000);\r\n\r\n    UPDATE Customer\r\n    SET points = points + @points_to_add,\r\n        member_tier = CASE\r\n            WHEN points + @points_to_add >= 1000 THEN 'GOLD'\r\n            WHEN points + @points_to_add >= 300  THEN 'SILVER'\r\n            ELSE 'BRONZE'\r\n        END,\r\n        updated_at = SYSDATETIME()\r\n    WHERE id = @customer_id;\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/StoredProcedure[@Name='sp_AddCustomerPoints' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_CompleteOrder]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/StoredProcedure[@Name='sp_CompleteOrder' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_CompleteOrder]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- SP: Hoàn thành order + trừ kho nguyên liệu\r\nCREATE   PROCEDURE [dbo].[sp_CompleteOrder]\r\n    @order_id   BIGINT,\r\n    @account_id INT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    BEGIN TRANSACTION;\r\n    BEGIN TRY\r\n        DECLARE @branch_id INT;\r\n        SELECT @branch_id = branch_id FROM [Order] WHERE id = @order_id;\r\n\r\n        -- Tính cost & trừ kho theo công thức\r\n        DECLARE @cost DECIMAL(15,2) = 0;\r\n\r\n        SELECT @cost = ISNULL(SUM(oi.quantity * r.quantity_required * bi.cost_per_unit), 0)\r\n        FROM Order_Item  oi\r\n        JOIN Recipe      r  ON r.menu_item_id  = oi.menu_item_id\r\n        JOIN Branch_Ingredient bi ON bi.ingredient_id = r.ingredient_id\r\n                                 AND bi.branch_id = @branch_id\r\n        WHERE oi.order_id = @order_id;\r\n\r\n        -- Trừ kho\r\n        UPDATE bi\r\n        SET bi.current_stock = bi.current_stock\r\n            - (SELECT SUM(oi.quantity * r.quantity_required)\r\n               FROM Order_Item oi\r\n               JOIN Recipe r ON r.menu_item_id = oi.menu_item_id\r\n                             AND r.ingredient_id = bi.ingredient_id\r\n               WHERE oi.order_id = @order_id)\r\n        FROM Branch_Ingredient bi\r\n        WHERE bi.branch_id = @branch_id;\r\n\r\n        -- Ghi Inventory_Transaction xuất kho\r\n        INSERT INTO Inventory_Transaction (branch_id, ingredient_id, employee_id, type, quantity, note)\r\n        SELECT @branch_id, r.ingredient_id, NULL, 'EXPORT',\r\n               -SUM(oi.quantity * r.quantity_required),\r\n               N'Xuất kho cho Order #' + CAST(@order_id AS NVARCHAR)\r\n        FROM Order_Item oi\r\n        JOIN Recipe r ON r.menu_item_id = oi.menu_item_id\r\n        WHERE oi.order_id = @order_id\r\n        GROUP BY r.ingredient_id;\r\n\r\n        -- Cập nhật order\r\n        UPDATE [Order]\r\n        SET order_status_id = 4,\r\n            cost_amount     = @cost,\r\n            updated_at      = SYSDATETIME()\r\n        WHERE id = @order_id;\r\n\r\n        -- Cập nhật trạng thái bàn về EMPTY\r\n        UPDATE Table_Cafe\r\n        SET status = 'EMPTY', updated_at = SYSDATETIME()\r\n        WHERE id = (SELECT table_id FROM [Order] WHERE id = @order_id)\r\n          AND status = 'OCCUPIED';\r\n\r\n        -- Lịch sử trạng thái\r\n        INSERT INTO Order_Status_History (order_id, status_id, changed_by)\r\n        VALUES (@order_id, 4, @account_id);\r\n\r\n        COMMIT TRANSACTION;\r\n    END TRY\r\n    BEGIN CATCH\r\n        ROLLBACK TRANSACTION;\r\n        THROW;\r\n    END CATCH;\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/StoredProcedure[@Name='sp_CompleteOrder' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_CreateOrder]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/StoredProcedure[@Name='sp_CreateOrder' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_CreateOrder]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- ================================================================\r\n-- PHẦN 12: STORED PROCEDURES HỖ TRỢ\r\n-- ================================================================\r\n\r\n-- SP: Tạo order mới và trả về ID\r\nCREATE   PROCEDURE [dbo].[sp_CreateOrder]\r\n    @branch_id      INT,\r\n    @shift_id       BIGINT,\r\n    @customer_id    INT,\r\n    @table_id       INT,\r\n    @order_type     VARCHAR(20),\r\n    @order_id       BIGINT OUTPUT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    INSERT INTO [Order] (branch_id, shift_id, customer_id, order_status_id, table_id, order_type, sub_total, discount_amount, final_amount)\r\n    VALUES (@branch_id, @shift_id, @customer_id, 1, @table_id, @order_type, 0, 0, 0);\r\n    SET @order_id = SCOPE_IDENTITY();\r\n\r\n    -- Ghi lịch sử trạng thái PENDING\r\n    INSERT INTO Order_Status_History (order_id, status_id) VALUES (@order_id, 1);\r\n\r\n    -- Cập nhật trạng thái bàn nếu DINE_IN\r\n    IF @order_type = 'DINE_IN' AND @table_id IS NOT NULL\r\n        UPDATE Table_Cafe SET status = 'OCCUPIED' WHERE id = @table_id;\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/StoredProcedure[@Name='sp_CreateOrder' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [dbo].[sp_RecalculateOrder]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/StoredProcedure[@Name='sp_RecalculateOrder' and @Schema='dbo']","object_type":"StoredProcedure"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["/****** Object:  StoredProcedure [dbo].[sp_RecalculateOrder]    Script Date: 24/04/2026 7:49:12 pm ******/\r\nSET ANSI_NULLS ON\r\n","GO\r\n","SET QUOTED_IDENTIFIER ON\r\n","GO\r\n","\r\n-- SP: Cập nhật tổng tiền order (gọi sau khi thêm/xóa item)\r\nCREATE   PROCEDURE [dbo].[sp_RecalculateOrder]\r\n    @order_id BIGINT\r\nAS\r\nBEGIN\r\n    SET NOCOUNT ON;\r\n    DECLARE @sub_total DECIMAL(15,2);\r\n\r\n    SELECT @sub_total = SUM(total_price) FROM Order_Item WHERE order_id = @order_id;\r\n    SET @sub_total = ISNULL(@sub_total, 0);\r\n\r\n    DECLARE @discount DECIMAL(15,2);\r\n    SELECT @discount = ISNULL(SUM(discount_value), 0)\r\n    FROM Order_Promotion WHERE order_id = @order_id;\r\n\r\n    UPDATE [Order]\r\n    SET sub_total      = @sub_total,\r\n        discount_amount = @discount,\r\n        final_amount   = @sub_total - @discount,\r\n        updated_at     = SYSDATETIME()\r\n    WHERE id = @order_id;\r\nEND;\r\nGO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']/StoredProcedure[@Name='sp_RecalculateOrder' and @Schema='dbo']","object_type":"StoredProcedure"}},{"cell_type":"markdown","source":["# [pbl3_cafe_management]"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']","object_type":"Database"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["USE [master]\r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']","object_type":"Database"}},{"outputs":[],"execution_count":0,"cell_type":"code","source":["ALTER DATABASE [pbl3_cafe_management] SET  READ_WRITE \r\n","GO\r\n"],"metadata":{"urn":"Server[@Name='LINH\\SQLEXPRESS']/Database[@Name='pbl3_cafe_management']","object_type":"Database"}}]}